<template>
  <div ref="page" class="catalog-admin">
    <AdminNav />
    <main>
      <header class="page-header" data-admin-reveal>
        <div>
          <span class="eyebrow"><i class="fa-solid fa-sparkles"></i> Gestión de catálogo</span>
          <h1>Construye tu<br><em>vitrina digital.</em></h1>
          <p>Publica productos y servicios que aparecen directamente en el sitio web.</p>
        </div>
        <div><button class="import-offers" :disabled="importing || loading" @click="loadOffers"><i :class="importing ? 'fa-solid fa-spinner fa-spin' : 'fa-solid fa-file-arrow-up'"></i> {{ importing ? 'Actualizando catálogo...' : 'Cargar ofertas PDF' }}</button><div class="header-metric"><i class="fa-solid fa-boxes-stacked"></i><strong>{{ items.length }}</strong><span>publicaciones</span></div></div>
      </header>

      <section class="workspace" data-admin-reveal>
        <form class="editor" @submit.prevent="saveItem">
          <div class="card-title"><div class="title-icon"><i :class="editingId ? 'fa-solid fa-pen-ruler' : 'fa-solid fa-circle-plus'"></i></div><div><span>{{ editingId ? 'Modo edición' : 'Nueva publicación' }}</span><h2>{{ editingId ? 'Ajusta los detalles' : 'Crear producto o servicio' }}</h2></div></div>

          <div class="form-body">
            <label class="field full"><span>Nombre visible</span><input v-model="form.name" required placeholder="Ej. Impresora Epson EcoTank"></label>
            <label class="field full"><span>Descripción</span><textarea v-model="form.description" required placeholder="Explica por qué este producto o servicio es relevante."></textarea></label>
            <div class="field-row"><label class="field"><span>Precio USD</span><div class="input-icon"><i class="fa-solid fa-dollar-sign"></i><input v-model.number="form.price" type="number" min="0" step="0.01" required></div></label><label class="field"><span>Tipo</span><div class="select-icon"><i class="fa-solid fa-tags"></i><select v-model="form.kind"><option value="product">Producto</option><option value="service">Servicio</option></select></div></label></div>
            <label class="field full"><span>Categoría</span><div class="select-icon"><i class="fa-solid fa-folder-open"></i><select v-model="form.category" required><option disabled value="">Selecciona una categoría</option><option v-for="category in categories" :key="category._id" :value="category._id">{{ category.name }}</option></select></div></label>

             <div class="image-upload"><div class="image-label"><span>Imagen principal</span><small>JPG, PNG, WebP o AVIF · Máx. 5 MB</small></div><label class="dropzone" :class="{ uploading, ready: form.imageUrl }"><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" @change="uploadImage"><i :class="uploading ? 'fa-solid fa-spinner fa-spin' : form.imageUrl ? 'fa-solid fa-circle-check' : 'fa-solid fa-cloud-arrow-up'"></i><strong>{{ uploading ? 'Subiendo nueva imagen...' : form.imageUrl ? 'Imagen lista para guardar' : 'Seleccionar una imagen' }}</strong><small>{{ form.imageUrl ? 'Selecciona otro archivo para reemplazar la imagen actual' : 'Se optimizará y guardará de forma segura' }}</small></label><div v-if="form.imageUrl" class="image-preview"><img :src="form.imageUrl" alt="Vista previa"><button type="button" @click="form.imageUrl = ''" aria-label="Quitar imagen"><i class="fa-solid fa-xmark"></i></button></div></div>

             <label class="field full optional"><span>URL externa de imagen <small>(opcional)</small></span><div class="input-icon"><i class="fa-solid fa-link"></i><input v-model="form.imageUrl" type="url" placeholder="https://..."></div></label>
             <div class="spec-editor"><div><span>Ficha técnica</span><small>Estos datos se muestran en la página del producto.</small></div><div v-for="(spec, index) in form.specifications" :key="index" class="spec-row"><input v-model="spec.label" placeholder="Ej. Procesador"><input v-model="spec.value" placeholder="Ej. Intel Core i5"><button type="button" aria-label="Eliminar especificación" @click="form.specifications?.splice(index, 1)"><i class="fa-solid fa-xmark"></i></button></div><button type="button" class="add-spec" @click="form.specifications?.push({ label: '', value: '' })"><i class="fa-solid fa-plus"></i> Agregar especificación</button></div>
            <label class="publish-toggle"><input v-model="form.active" type="checkbox"><span class="toggle"><i class="fa-solid fa-check"></i></span><div><strong>Publicar inmediatamente</strong><small>Será visible en el sitio público al guardar.</small></div></label>
          </div>

          <footer class="editor-footer"><button v-if="editingId" type="button" class="secondary" @click="resetForm"><i class="fa-solid fa-arrow-left"></i> Cancelar</button><button type="submit" class="primary" :disabled="saving || uploading"><i :class="saving ? 'fa-solid fa-spinner fa-spin' : 'fa-solid fa-floppy-disk'"></i>{{ saving ? 'Guardando...' : editingId ? 'Guardar cambios' : 'Publicar ahora' }}</button></footer>
        </form>

        <aside class="sidebar-card">
          <div class="side-title"><div><span>Organización</span><h2>Categorías</h2></div><i class="fa-solid fa-shapes"></i></div>
           <form class="category-form" @submit.prevent="addCategory"><input v-model="newCategory" placeholder="Nueva categoría" required :disabled="categorySaving"><button :disabled="categorySaving" aria-label="Agregar categoría"><i :class="categorySaving ? 'fa-solid fa-spinner fa-spin' : 'fa-solid fa-plus'"></i></button></form>
          <div class="category-list"><div v-for="category in categories" :key="category._id"><span><i class="fa-solid fa-folder"></i>{{ category.name }}</span><button @click="removeCategory(category._id)" aria-label="Eliminar categoría"><i class="fa-solid fa-trash-can"></i></button></div><p v-if="!categories.length"><i class="fa-regular fa-folder-open"></i> Crea tu primera categoría para comenzar.</p></div>
          <div class="tip"><i class="fa-solid fa-lightbulb"></i><p>Las categorías permiten organizar el catálogo y facilitar la navegación de tus clientes.</p></div>
        </aside>
      </section>

      <section class="inventory" data-admin-reveal>
        <div class="inventory-header"><div><span class="eyebrow"><i class="fa-solid fa-grid-2"></i> Inventario</span><h2>Todo lo publicado</h2></div><div class="filters"><button :class="{ selected: filter === 'all' }" @click="filter = 'all'">Todos</button><button :class="{ selected: filter === 'product' }" @click="filter = 'product'">Productos</button><button :class="{ selected: filter === 'service' }" @click="filter = 'service'">Servicios</button></div></div>
         <div v-if="loading" class="empty-state"><i class="fa-solid fa-spinner fa-spin"></i><h3>Cargando catálogo</h3><p>Estamos preparando tus productos y categorías.</p></div><div v-else-if="filteredItems.length" class="item-list"><article v-for="item in filteredItems" :key="item._id" class="item-card"><div class="item-image"><img v-if="item.imageUrl" :src="item.imageUrl" :alt="item.name"><i v-else class="fa-solid fa-image"></i><span :class="{ draft: !item.active }">{{ item.active ? 'Publicado' : 'Borrador' }}</span></div><div class="item-copy"><span>{{ item.kind === 'product' ? 'Producto' : 'Servicio' }} · {{ item.category.name }}</span><h3>{{ item.name }}</h3><p>{{ item.description }}</p><strong>${{ item.price.toFixed(2) }}</strong></div><div class="item-actions"><button @click="edit(item)"><i class="fa-solid fa-pen-ruler"></i> Editar ficha e imagen</button><button class="delete" :disabled="deletingId === item._id" @click="removeItem(item._id)"><i :class="deletingId === item._id ? 'fa-solid fa-spinner fa-spin' : 'fa-solid fa-trash-can'"></i></button></div></article></div><div v-else class="empty-state"><i class="fa-solid fa-box-open"></i><h3>No hay publicaciones aquí</h3><p>Crea el primer producto o servicio desde el editor.</p></div>
      </section>
    </main>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import AdminNav from '@/components/AdminNav.vue'
import { createCatalogItem, createCategory, deleteCatalogItem, deleteCategory, getCatalog, getCategories, importOffersCatalog, updateCatalogItem, uploadCatalogImage, type CatalogItem, type CatalogPayload, type Category } from '@/services/catalog'
import { useAdminEntrance } from '@/composables/useAdminEntrance'

const token = sessionStorage.getItem('admin-token') || ''
const page = useAdminEntrance()
void page
const categories = ref<Category[]>([])
const items = ref<CatalogItem[]>([])
const newCategory = ref('')
const editingId = ref('')
const uploading = ref(false)
const saving = ref(false)
const importing = ref(false)
const loading = ref(true)
const categorySaving = ref(false)
const deletingId = ref('')
const filter = ref<'all' | 'product' | 'service'>('all')
const form = reactive<CatalogPayload>({ name: '', description: '', price: 0, imageUrl: '', kind: 'product', active: true, category: '', specifications: [] })
const filteredItems = computed(() => filter.value === 'all' ? items.value : items.value.filter(item => item.kind === filter.value))
const resetForm = () => { editingId.value = ''; Object.assign(form, { name: '', description: '', price: 0, imageUrl: '', kind: 'product', active: true, category: '', specifications: [] }) }
const load = async () => { loading.value = true; try { [categories.value, items.value] = await Promise.all([getCategories(), getCatalog(undefined, true, token)]) } finally { loading.value = false } }
const addCategory = async () => { categorySaving.value = true; try { await createCategory(newCategory.value, token); newCategory.value = ''; await load() } finally { categorySaving.value = false } }
const removeCategory = async (id: string) => { if (confirm('¿Eliminar esta categoría?')) { await deleteCategory(id, token); await load() } }
const uploadImage = async (event: Event) => { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; uploading.value = true; try { form.imageUrl = (await uploadCatalogImage(file, token)).url } finally { uploading.value = false } }
const saveItem = async () => { saving.value = true; try { form.specifications = form.specifications?.filter(spec => spec.label.trim() && spec.value.trim()); if (editingId.value) await updateCatalogItem(editingId.value, form, token); else await createCatalogItem(form, token); resetForm(); await load() } finally { saving.value = false } }
const edit = (item: CatalogItem) => { editingId.value = item._id; Object.assign(form, { name: item.name, description: item.description, price: item.price, imageUrl: item.imageUrl, kind: item.kind, active: item.active, category: item.category._id, specifications: item.specifications ? item.specifications.map(spec => ({ ...spec })) : [] }); window.scrollTo({ top: 0, behavior: 'smooth' }) }
const removeItem = async (id: string) => { if (confirm('¿Eliminar esta publicación?')) { deletingId.value = id; try { await deleteCatalogItem(id, token); await load() } finally { deletingId.value = '' } } }
const loadOffers = async () => { if (!confirm('Se cargarán o actualizarán las 19 ofertas disponibles del PDF. ¿Continuar?')) return; importing.value = true; try { const { imported } = await importOffersCatalog(token); alert(`${imported} ofertas cargadas correctamente.`); await load() } finally { importing.value = false } }
onMounted(load)
</script>

