r-radius:20px; background:#cdd7d5; transition:.2s ease; i { width:18px; height:18px; display:flex; align-items:center; justify-content:center; border-radius:50%; background:#fff; color:transparent; font-size:9px; transition:.2s ease; } } input:checked + .toggle { justify-content:flex-end; background:#3195c4; i { color:#3195c4; } } div { display:flex; flex-direction:column; gap:2px; } strong { font-size:13px; } small { color:#738286; font-size:11px; } }.editor-footer { padding:16px 22px; display:flex; justify-content:flex-end; gap:9px; border-top:1px solid #e8eeeb; }.editor-footer button { display:flex; align-items:center; gap:8px; border:0; border-radius:9px; padding:12px 15px; font-weight:900; cursor:pointer; }.primary { background:#247fb0; color:#fff; }.primary:disabled { opacity:.65; cursor:wait; }.secondary { background:#e7edeb; color:#405258; }.sidebar-card { padding:22px; }.side-title { display:flex; align-items:start; justify-content:space-between; }.side-title>i { color:#5aaed9; font-size:22px; }.category-form { display:flex; gap:8px; margin:20px 0 12px; }.category-form button { width:42px; border:0; border-radius:9px; background:#18313c; color:#fff; cursor:pointer; }.category-list { display:flex; flex-direction:column; }.category-list>div { display:flex; align-items:center; justify-content:space-between; padding:10px 0; border-top:1px solid #e7edeb; }.category-list span { display:flex; gap:8px; align-items:center; font-size:13px; font-weight:700; }.category-list span i { color:#4ba0cc; }.category-list button { border:0; background:transparent; color:#a4b0b0; cursor:pointer; &:hover { color:#d44d5d; } }.category-list p { padding:17px 0; color:#809094; font-size:12px; line-height:1.5; }.tip { display:flex; gap:9px; margin-top:18px; padding:13px; border-radius:10px; background:#eef7fa; color:#4e6671; }.tip i { color:#3d9dcc; }.tip p { font-size:11px; line-height:1.5; }.inventory { margin-top:22px; padding:22px; }.inventory-header { display:flex; flex-direction:column; gap:16px; margin-bottom:17px; }.inventory-header h2 { margin-top:6px; font-size:25px; letter-spacing:-.05em; }.filters { display:flex; gap:6px; }.filters button { border:1px solid #d8e2df; border-radius:20px; padding:7px 10px; background:transparent; color:#68797e; font-size:11px; font-weight:800; cursor:pointer; }.filters button.selected { border-color:#348ebe; background:#348ebe; color:#fff; }.item-list { display:flex; flex-direction:column; border-top:1px solid #e4ebe8; }.item-card { padding:15px 0; display:flex; flex-wrap:wrap; align-items:center; gap:12px; border-bottom:1px solid #e4ebe8; }.item-image { position:relative; width:60px; height:60px; display:flex; align-items:center; justify-content:center; overflow:hidden; border-radius:10px; background:#e6eef0; color:#6ca7c4; }.item-image img { width:100%; height:100%; object-fit:cover; }.item-image span { position:absolute; bottom:3px; left:3px; padding:3px 5px; border-radius:4px; background:rgba(16,38,45,.78); color:#fff; font-size:8px; font-weight:900; text-transform:uppercase; }.item-image span.draft { background:#936b2c; }.item-copy { min-width:160px; flex:1; display:flex; flex-direction:column; gap:4px; }.item-copy>span { color:#438bb2; font-size:10px; font-weight:900; text-transform:uppercase; }.item-copy h3 { font-size:15px; }.item-copy p { display:none; color:#6a7a7d; font-size:12px; line-height:1.45; }.item-copy strong { color:#1b6f9e; font-size:14px; }.item-actions { display:flex; gap:6px; }.item-actions button { border:0; border-radius:7px; padding:8px 10px; background:#e9efed; color:#43565b; font-size:11px; font-weight:900; cursor:pointer; }.item-actions .delete { color:#c84b59; }.empty-state { padding:60px 20px; display:flex; flex-direction:column; align-items:center; gap:9px; text-align:center; color:#728286; }.empty-state i { color:#5ba8d0; font-size:32px; }.empty-state h3 { color:#30454b; }.empty-state p { font-size:13px; }
